I'll show you debounced search examples. Which framework?

Here's **React** (most common):

```jsx
import { useState, useEffect, useRef } from 'react';

function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  useEffect(() => {
    // Clear previous timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    // Skip empty query
    if (!query.trim()) {
      setResults([]);
      return;
    }

    // Debounce: only call API after 500ms of no typing
    timeoutRef.current = setTimeout(async () => {
      const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
      const data = await res.json();
      setResults(data);
    }, 500);

    // Cleanup on unmount
    return () => clearTimeout(timeoutRef.current);
  }, [query]);

  return (
    <div>
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      <ul>
        {results.map((r) => (
          <li key={r.id}>{r.name}</li>
        ))}
      </ul>
    </div>
  );
}
```

Or **vanilla JS**:

```js
let timeoutId = null;

const searchInput = document.querySelector('#search');
searchInput.addEventListener('input', (e) => {
  clearTimeout(timeoutId);

  const query = e.target.value.trim();
  if (!query) return;

  timeoutId = setTimeout(async () => {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    const data = await res.json();
    // render results
    console.log(data);
  }, 500);
});
```

**Key:** `clearTimeout()` before new search kills pending calls. Only API fires after 500ms silence. Adjust delay (500ms) per your UX.

